// [name, zip bytes, expected reason or null]
export function hygieneFixtures() {
  return Object.entries(cases).map(([name, [entries, want, noSkill]]) => [
    name, buildZip(noSkill ? entries : [skill, ...entries]), want,
  ]);
}
